albumsData = FileAttachment("data/similarity.json").json()

artists = ["All", ...new Set(albumsData.map(d =&gt; d.artist).sort())]

viewof selectedArtist = Inputs.select(artists, { label: "Select an artist:" })

filteredAlbums = selectedArtist === "All" 
  ? albumsData 
  : albumsData.filter(d =&gt; d.artist === selectedArtist)

viewof album = Inputs.select(
  new Map(filteredAlbums.map(d =&gt; [selectedArtist === "All" ? d.display : d.title, d.file])),
  { label: "Select an album:" }
)

html`&lt;div style="margin-top: 20px;"&gt;
  &lt;img src="${album}" alt="Album cover" style="max-width: 400px; width: 100%; border-radius: 8px; box-shadow: 0 4px 8px rgba(0,0,0,0.15);"&gt;
&lt;/div&gt;`










































currentAlbum = albumsData.find(d =&gt; d.file === album)

similarAlbums = currentAlbum?.similar.slice(0, 3) ?? []

differentAlbums = currentAlbum ? currentAlbum.similar.slice(-3).reverse() : []

html`
&lt;div style="margin-top: 30px;"&gt;
  &lt;h3&gt;Most Similar Albums&lt;/h3&gt;
  &lt;div style="display: flex; gap: 20px; flex-wrap: wrap;"&gt;
    ${similarAlbums.map(d =&gt; html`
      &lt;div style="text-align: center; width: 160px;"&gt;
        &lt;img src="${d.file}" alt="${d.display}" style="width: 100%; border-radius: 8px; box-shadow: 0 4px 8px rgba(0,0,0,0.15);"&gt;
        &lt;p style="margin-top: 8px; font-size: 14px;"&gt;${d.display}&lt;/p&gt;
      &lt;/div&gt;
    `)}
  &lt;/div&gt;
&lt;/div&gt;

&lt;div style="margin-top: 30px;"&gt;
  &lt;h3&gt;Most Different Albums&lt;/h3&gt;
  &lt;div style="display: flex; gap: 20px; flex-wrap: wrap;"&gt;
    ${differentAlbums.map(d =&gt; html`
      &lt;div style="text-align: center; width: 160px;"&gt;
        &lt;img src="${d.file}" alt="${d.display}" style="width: 100%; border-radius: 8px; box-shadow: 0 4px 8px rgba(0,0,0,0.15);"&gt;
        &lt;p style="margin-top: 8px; font-size: 14px;"&gt;${d.display}&lt;/p&gt;
      &lt;/div&gt;
    `)}
  &lt;/div&gt;
&lt;/div&gt;
`
